test("pages at 20 candidates, bounds visible fields and downloads every original byte", async () => {
  const response = parseRegistryResponse(RAW, {
    registry: "sam-exclusions",
    target: { uei: "ABCDEFGHIJKL" },
    scope_label: null,
  });
  let downloaded: Blob | null = null;
  vi.stubGlobal(
    "URL",
    class extends URL {
      static createObjectURL(value: Blob) {
        downloaded = value;
        return "blob:synthetic-registry-boundary";
      }
      static revokeObjectURL = vi.fn();
    },
  );
  vi.spyOn(HTMLAnchorElement.prototype, "click").mockImplementation(() => {});
  vi.mocked(api.collectRegistry).mockResolvedValue(response);
  render(<RegistryCollectAction freshAuth verifyAuth={async () => true} />);
  fireEvent.change(screen.getByLabelText("Registry"), {
    target: { value: "sam-exclusions" },
  });
  fireEvent.change(screen.getByLabelText("Unique Entity ID (UEI)"), {
    target: { value: "ABCDEFGHIJKL" },
  });
  fireEvent.click(screen.getByRole("button", { name: "Collect registry" }));
  await screen.findByRole("region", { name: "Registry result" });
  const candidates = screen.getByLabelText("Candidate observations");
  expect(
    within(candidates).getAllByText(/^Candidate [0-9]+; match basis:/),
  ).toHaveLength(20);
  expect(
    screen.getByText(/Showing 1 to 20 of 21 observations/),
  ).toBeInTheDocument();
  expect(
    screen.getByRole("button", { name: "Previous candidates" }),
  ).toBeDisabled();
  const literal = [...candidates.querySelectorAll("pre")].find((item) =>
    item.textContent?.includes("<img src=x onerror=alert(1)>"),
  );
  expect(literal).toBeDefined();
  expect(candidates.querySelector("img")).toBeNull();
  expect(
    new TextEncoder().encode(literal!.textContent!).length,
  ).toBeLessThanOrEqual(16_384);
  expect(literal!.textContent).not.toContain("�");
  expect(
    screen.getByText(/The full JSON download includes the complete value/),
  ).toBeInTheDocument();
  fireEvent.click(screen.getByRole("button", { name: "Next candidates" }));
  expect(
    within(candidates).getAllByText(/^Candidate [0-9]+; match basis:/),
  ).toHaveLength(1);
  expect(
    screen.getByText(/Showing 21 to 21 of 21 observations/),
  ).toBeInTheDocument();
  expect(
    screen.getByRole("button", { name: "Next candidates" }),
  ).toBeDisabled();
  fireEvent.click(screen.getByRole("button", { name: "Previous candidates" }));
  expect(
    within(candidates).getAllByText(/^Candidate [0-9]+; match basis:/),
  ).toHaveLength(20);
  fireEvent.click(
    screen.getByRole("button", { name: "Download full registry JSON" }),
  );
  expect(await (downloaded as unknown as Blob).text()).toBe(RAW);
});
